{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE vahdam_db.maplemonk.vahdam_amazon_pnl_overall_fy27_onwards AS ( WITH asin_map_unpivot AS ( SELECT TRIM(asin) AS asin, src, BRAND AS brand, \"Common SKU ID\" AS common_sku_id, \"Common SKU Description\" AS common_sku_description, CATEGORY AS category, \"Sub-category\" AS sub_category, \"Type-3\" AS amz_category FROM vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_PRODUCT_MAPPING UNPIVOT (asin FOR src IN ( \"Amazon USA\",\"Amazon CA\",\"Amazon DE\",\"Amazon ES\",\"Amazon FR\",\"Amazon IT\", \"Amazon UK\",\"Amazon UAE\",\"Amazon AUS\",\"Amazon JP\",\"Amazon SG\",\"Amazon India\", \"Amazon US 1P\",\"Amazon UK 1P\",\"Amazon EU 1P\",\"Amazon CA 1P\",\"Amazon India 1P\" )) WHERE asin IS NOT NULL AND TRIM(asin) <> \'\' ), asin_geo_map AS ( SELECT asin, brand, common_sku_id, common_sku_description, category, sub_category, amz_category, CASE WHEN src ILIKE \'%1P\' THEN \'Amazon_1P\' ELSE \'Amazon_3P\' END AS channel, CASE WHEN UPPER(src)=\'AMAZON USA\' THEN \'USA\' WHEN UPPER(src)=\'AMAZON US 1P\' THEN \'USA\' WHEN UPPER(src)=\'AMAZON INDIA\' THEN \'IN\' WHEN UPPER(src)=\'AMAZON INDIA 1P\' THEN \'IN\' ELSE UPPER(REPLACE(REPLACE(src,\'Amazon \',\'\'),\' 1P\',\'\')) END AS geo FROM asin_map_unpivot WHERE UPPER(src) <> \'AMAZON EU 1P\' UNION ALL SELECT m.asin, m.brand, m.common_sku_id, m.common_sku_description, m.category, m.sub_category, m.amz_category, \'Amazon_1P\' AS channel, g.geo FROM asin_map_unpivot m CROSS JOIN (SELECT \'DE\' geo UNION ALL SELECT \'ES\' UNION ALL SELECT \'FR\' UNION ALL SELECT \'IT\') g WHERE UPPER(m.src) = \'AMAZON EU 1P\' ), asin_geo_map_dedup AS ( SELECT asin, channel, geo, ANY_VALUE(brand) AS brand, ANY_VALUE(common_sku_id) AS common_sku_id, ANY_VALUE(common_sku_description) AS common_sku_description, ANY_VALUE(category) AS category, ANY_VALUE(sub_category) AS sub_category, ANY_VALUE(amz_category) AS amz_category FROM asin_geo_map GROUP BY asin, channel, geo ), cogs_sheet AS ( SELECT TRIM(MATERIAL) AS common_sku_id, TRY_TO_DECIMAL(REPLACE(COGS,\',\',\'\'),30,5) AS cogs_per_unit_inr FROM vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_COGS_SHEET WHERE MATERIAL IS NOT NULL ), cogs_budget_csku AS ( SELECT TRIM(\"Common SKU\") AS common_sku_id, AVG( TRY_TO_DECIMAL(REPLACE(COGS_PER_UNIT,\',\',\'\'),30,5) * TRY_TO_DECIMAL(REPLACE(FX,\',\',\'\'),30,5) ) AS cogs_per_unit_inr_csku FROM vahdam_db.maplemonk.VAHDAM_BUDGET_AMAZON_3P___1P_BUDGET WHERE TRIM(\"Common SKU\") IS NOT NULL AND TRIM(\"Common SKU\") <> \'\' GROUP BY TRIM(\"Common SKU\") HAVING AVG( TRY_TO_DECIMAL(REPLACE(COGS_PER_UNIT,\',\',\'\'),30,5) * TRY_TO_DECIMAL(REPLACE(FX,\',\',\'\'),30,5) ) IS NOT NULL ), settlement_latest AS ( SELECT ASIN, UPPER(GEO) AS geo, CASE WHEN NULLIF(UNITS,0) IS NULL THEN NULL ELSE FBA_FEES/UNITS END AS lastmile_per_unit_local_settlement, CASE WHEN NULLIF(SALES,0) IS NULL THEN NULL ELSE COMMISSION/SALES END AS commission_pct_settlement FROM (SELECT s.*, ROW_NUMBER() OVER (PARTITION BY s.ASIN, UPPER(s.GEO) ORDER BY s.DATE DESC) rn FROM vahdam_db.maplemonk.AMAZON_3P_SETTLEMENT s WHERE UPPER(s.CHANNEL)=\'AMAZON 3P\') WHERE rn=1 ), india_perunit AS ( SELECT s.asin, s.lastmile_per_unit, s.commission_pct, w.storage_per_unit FROM ( SELECT asin, lastmile_per_unit, commission_pct FROM ( SELECT asin, DIV0(-1*last_mile, NULLIF(units,0)) AS lastmile_per_unit, DIV0(-1*commission, NULLIF(sales_net,0)) AS commission_pct, ROW_NUMBER() OVER (PARTITION BY asin ORDER BY day DESC) rn FROM vahdam_db.maplemonk.vahdam_in_3p_finevents_actuals WHERE units > 0 ) WHERE rn = 1 ) s LEFT JOIN ( SELECT asin, DIV0(-1*SUM(storage), NULLIF(SUM(units),0)) AS storage_per_unit FROM vahdam_db.maplemonk.vahdam_in_3p_finevents_actuals GROUP BY asin ) w ON w.asin = s.asin ), india_ob AS ( SELECT TRIM(ASIN) AS asin, AVG(TRY_TO_DECIMAL(REPLACE(OB_PU,\',\',\'\'),30,5)) AS ob_per_unit FROM vahdam_db.maplemonk.FY27_INPUTS_AMAZON_INDIA_COSTS WHERE ASIN IS NOT NULL AND TRY_TO_DECIMAL(REPLACE(OB_PU,\',\',\'\'),30,5) IS NOT NULL GROUP BY 1 ), budget_raw AS ( SELECT TRIM(ASIN) AS asin, TRIM(\"Common SKU\") AS common_sku_id, UPPER(GEOGRAPHY) AS geo, CASE WHEN UPPER(PLATFORM) LIKE \'%1P%\' THEN \'Amazon_1P\' WHEN UPPER(PLATFORM) LIKE \'%3P%\' THEN \'Amazon_3P\' ELSE PLATFORM END AS channel, DATE_TRUNC(\'MONTH\', COALESCE( TRY_TO_DATE(\"MONTH\", \'DD-Mon-YY\'), TRY_TO_DATE(\'1-\' || \"MONTH\", \'DD-Mon-YY\'), TRY_TO_DATE(\"MONTH\", \'MM-DD-YYYY\'), TRY_TO_DATE(\"MONTH\", \'YYYY-MM-DD\') )) AS month_start, TRY_TO_DECIMAL(REPLACE(FX,\',\',\'\'),30,5) AS fx, TRY_TO_DECIMAL(REPLACE(QTY,\',\',\'\'),30,5) AS qty, TRY_TO_DECIMAL(REPLACE(\"Net Sales\",\',\',\'\'),30,5) AS net_sales, TRY_TO_DECIMAL(REPLACE(COGS,\',\',\'\'),30,5) AS cogs, TRY_TO_DECIMAL(REPLACE(\"Additional Duty\",\',\',\'\'),30,5) AS additional_duty, TRY_TO_DECIMAL(REPLACE(COMMISSION,\',\',\'\'),30,5) AS commission, TRY_TO_DECIMAL(REPLACE(OUTBOUND,\',\',\'\'),30,5) AS outbound, TRY_TO_DECIMAL(REPLACE(\"3PL\",\',\',\'\'),30,5) AS three_pl, TRY_TO_DECIMAL(REPLACE(STORAGE,\',\',\'\'),30,5) AS storage, TRY_TO_DECIMAL(REPLACE(\"Last mile\",\',\',\'\'),30,5) AS last_mile, TRY_TO_DECIMAL(REPLACE(\"Performance Marketing\",\',\',\'\'),30,5) AS performance_marketing, TRY_TO_DECIMAL(REPLACE(COGS_PER_UNIT,\',\',\'\'),30,5) AS cogs_per_unit_local, TRY_TO_DECIMAL(REPLACE(OUTBOUND_PER_UNIT,\',\',\'\'),30,5) AS outbound_per_unit_local, TRY_TO_DECIMAL(REPLACE(\"3pl_per_unit\",\',\',\'\'),30,5) AS three_pl_per_unit_local, TRY_TO_DECIMAL(REPLACE(STORAGE_PER_UNIT,\',\',\'\'),30,5) AS storage_per_unit_local, TRY_TO_DECIMAL(REPLACE(LASTMILE_PER_UNIT,\',\',\'\'),30,5) AS lastmile_per_unit_local, TRY_TO_DECIMAL(REPLACE(COMMISSION_PER_UNIT,\',\',\'\'),30,5) AS commission_per_unit_local, TRY_TO_DECIMAL(REPLACE(ADDITIONAL_DUTY_PER_UNIT,\',\',\'\'),30,5) AS additional_duty_per_unit_local FROM vahdam_db.maplemonk.VAHDAM_BUDGET_AMAZON_3P___1P_BUDGET ), fx_map AS ( SELECT geo, month_start, MAX(fx) AS fx FROM budget_raw WHERE fx IS NOT NULL AND month_start IS NOT NULL GROUP BY geo, month_start ), fx_geo_avg AS (SELECT geo, AVG(fx) AS fx_geo_avg FROM fx_map GROUP BY geo), geo_currency AS ( SELECT UPPER(GEO) AS geo, ANY_VALUE(CURRENCY) AS currency_local FROM vahdam_db.maplemonk.VAHDAM_AMAZON_SALES_MARKETING WHERE CURRENCY IS NOT NULL AND TRIM(CURRENCY) <> \'\' GROUP BY UPPER(GEO) ), budget_asin AS ( SELECT geo, channel, month_start, asin, ANY_VALUE(common_sku_id) AS common_sku_id, MAX(fx) AS fx, SUM(qty) AS qty, SUM(net_sales) AS net_sales_local, SUM(cogs) AS cogs_local, SUM(additional_duty) AS additional_duty_local, SUM(commission) AS commission_local, SUM(outbound) AS outbound_local, SUM(three_pl) AS three_pl_local, SUM(storage) AS storage_local, SUM(last_mile) AS last_mile_local, SUM(performance_marketing) AS pm_spend_local, AVG(cogs_per_unit_local) AS cogs_per_unit_local, AVG(outbound_per_unit_local) AS outbound_per_unit_local, AVG(three_pl_per_unit_local) AS three_pl_per_unit_local, AVG(storage_per_unit_local) AS storage_per_unit_local, AVG(lastmile_per_unit_local) AS lastmile_per_unit_local, AVG(commission_per_unit_local) AS commission_per_unit_local, AVG(additional_duty_per_unit_local) AS additional_duty_per_unit_local, CASE WHEN NULLIF(SUM(net_sales),0) IS NULL THEN NULL ELSE SUM(commission)/NULLIF(SUM(net_sales),0) END AS commission_pct_budget_asin, CASE WHEN COALESCE(SUM(additional_duty),0) > 0 OR COALESCE(AVG(additional_duty_per_unit_local),0) > 0 THEN 1 ELSE 0 END AS has_additional_duty_flag FROM budget_raw WHERE month_start IS NOT NULL AND asin IS NOT NULL GROUP BY geo, channel, month_start, asin ), budget_pkg AS ( SELECT geo, channel, month_start, LEFT(common_sku_id,6) AS pkg6, ANY_VALUE(outbound_per_unit_local) AS outbound_per_unit_local_pkg, ANY_VALUE(lastmile_per_unit_local) AS lastmile_per_unit_local_pkg, ANY_VALUE(three_pl_per_unit_local) AS three_pl_per_unit_local_pkg, ANY_VALUE(storage_per_unit_local) AS storage_per_unit_local_pkg FROM budget_raw WHERE month_start IS NOT NULL AND common_sku_id IS NOT NULL AND LENGTH(common_sku_id) >= 6 GROUP BY geo, channel, month_start, LEFT(common_sku_id,6) ), month_spine AS ( SELECT DISTINCT month_start FROM budget_raw WHERE month_start IS NOT NULL UNION SELECT DISTINCT DATE_TRUNC(\'MONTH\', DAY) FROM vahdam_db.maplemonk.VAHDAM_AMAZON_SALES_MARKETING WHERE DAY IS NOT NULL ), budget_asin_keys AS (SELECT DISTINCT geo, channel, asin FROM budget_asin), budget_asin_ff AS ( SELECT s.month_start, k.geo, k.channel, k.asin, LAST_VALUE(b.outbound_per_unit_local) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.asin ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS outbound_per_unit_local_ff, LAST_VALUE(b.three_pl_per_unit_local) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.asin ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS three_pl_per_unit_local_ff, LAST_VALUE(b.storage_per_unit_local) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.asin ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS storage_per_unit_local_ff, LAST_VALUE(b.lastmile_per_unit_local) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.asin ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS lastmile_per_unit_local_ff, LAST_VALUE(b.commission_pct_budget_asin) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.asin ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS commission_pct_budget_asin_ff, LAST_VALUE(b.has_additional_duty_flag) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.asin ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS has_additional_duty_flag_ff, LAST_VALUE(CASE WHEN b.asin IS NOT NULL THEN s.month_start END) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.asin ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS budget_month_used FROM month_spine s CROSS JOIN budget_asin_keys k LEFT JOIN budget_asin b ON b.geo = k.geo AND b.channel = k.channel AND b.asin = k.asin AND b.month_start = s.month_start ), budget_pkg_keys AS (SELECT DISTINCT geo, channel, pkg6 FROM budget_pkg), budget_pkg_ff AS ( SELECT s.month_start, k.geo, k.channel, k.pkg6, LAST_VALUE(p.outbound_per_unit_local_pkg) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.pkg6 ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS outbound_per_unit_local_pkg_ff, LAST_VALUE(p.lastmile_per_unit_local_pkg) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.pkg6 ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS lastmile_per_unit_local_pkg_ff, LAST_VALUE(p.three_pl_per_unit_local_pkg) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.pkg6 ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS three_pl_per_unit_local_pkg_ff, LAST_VALUE(p.storage_per_unit_local_pkg) IGNORE NULLS OVER (PARTITION BY k.geo,k.channel,k.pkg6 ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS storage_per_unit_local_pkg_ff FROM month_spine s CROSS JOIN budget_pkg_keys k LEFT JOIN budget_pkg p ON p.geo = k.geo AND p.channel = k.channel AND p.pkg6 = k.pkg6 AND p.month_start = s.month_start ), budget_asin_anychannel AS ( SELECT geo, month_start, asin, AVG(outbound_per_unit_local) AS outbound_per_unit_local_xc, AVG(three_pl_per_unit_local) AS three_pl_per_unit_local_xc, AVG(storage_per_unit_local) AS storage_per_unit_local_xc FROM budget_raw WHERE month_start IS NOT NULL AND asin IS NOT NULL GROUP BY geo, month_start, asin ), budget_pkg_anychannel AS ( SELECT geo, month_start, LEFT(common_sku_id,6) AS pkg6, ANY_VALUE(outbound_per_unit_local) AS outbound_per_unit_local_pkg_xc, ANY_VALUE(three_pl_per_unit_local) AS three_pl_per_unit_local_pkg_xc, ANY_VALUE(storage_per_unit_local) AS storage_per_unit_local_pkg_xc FROM budget_raw WHERE month_start IS NOT NULL AND common_sku_id IS NOT NULL AND LENGTH(common_sku_id) >= 6 GROUP BY geo, month_start, LEFT(common_sku_id,6) ), budget_days AS ( SELECT month_start, DAY(LAST_DAY(month_start)) AS days_in_month FROM (SELECT DISTINCT month_start FROM budget_raw WHERE month_start IS NOT NULL) ), day_offsets AS (SELECT SEQ4() AS d_off FROM TABLE(GENERATOR(ROWCOUNT => 31))), budget_daily AS ( SELECT DATEADD(day, o.d_off, b.month_start) AS day, b.channel, b.geo, b.asin, b.qty/NULLIF(d.days_in_month,0) AS qty_budget, b.net_sales_local/NULLIF(d.days_in_month,0) AS sales_budget_local, b.cogs_local/NULLIF(d.days_in_month,0) AS cogs_budget_local, b.additional_duty_local/NULLIF(d.days_in_month,0) AS additional_duty_budget_local, b.commission_local/NULLIF(d.days_in_month,0) AS commission_budget_local, b.outbound_local/NULLIF(d.days_in_month,0) AS outbound_budget_local, b.three_pl_local/NULLIF(d.days_in_month,0) AS three_pl_budget_local, b.storage_local/NULLIF(d.days_in_month,0) AS storage_budget_local, b.last_mile_local/NULLIF(d.days_in_month,0) AS last_mile_budget_local, b.pm_spend_local/NULLIF(d.days_in_month,0) AS pm_spend_budget_local FROM budget_asin b JOIN budget_days d ON d.month_start=b.month_start JOIN day_offsets o ON o.d_off<d.days_in_month ), actuals AS ( SELECT DAY AS day, CASE WHEN UPPER(MARKETPLACE)=\'AMAZON_1P\' THEN \'Amazon_1P\' WHEN UPPER(MARKETPLACE)=\'AMAZON_3P\' THEN \'Amazon_3P\' ELSE MARKETPLACE END AS channel, UPPER(GEO) AS geo, ASIN AS asin, ANY_VALUE(CURRENCY) AS currency_local, SUM(QUANTITY) AS qty_actual, SUM(SALES) AS sales_actual_local, SUM(SPEND) AS pm_spend_actual_local, SUM(GOOGLE_SPEND) AS google_spend_actual_local FROM vahdam_db.maplemonk.VAHDAM_AMAZON_SALES_MARKETING GROUP BY DAY, MARKETPLACE, UPPER(GEO), ASIN ), india_pm_src AS ( SELECT DATE AS day, COALESCE(ASIN, REGEXP_SUBSTR(CAMPAIGNNAME,\'B0[A-Z0-9]{8}\')) AS asin, SPEND AS spend FROM vahdam_db.maplemonk.amazonads_in_marketing WHERE DATE IS NOT NULL AND SPEND IS NOT NULL ), india_pm_total_day AS (SELECT day, SUM(spend) AS tot_spend FROM india_pm_src GROUP BY 1), india_pm_direct AS (SELECT day, asin, SUM(spend) AS spend FROM india_pm_src WHERE asin IS NOT NULL GROUP BY 1,2), india_sales AS (SELECT day, asin, SUM(sales_actual_local) AS asin_sales FROM actuals WHERE geo=\'IN\' GROUP BY 1,2), india_day_sales AS (SELECT day, SUM(sales_actual_local) AS day_sales FROM actuals WHERE geo=\'IN\' GROUP BY 1), india_pm_matched AS ( SELECT s.day, SUM(d.spend) AS matched_spend FROM india_sales s JOIN india_pm_direct d ON d.day=s.day AND d.asin=s.asin GROUP BY 1 ), india_pm AS ( SELECT s.day, s.asin, IFNULL(d.spend,0) + (IFNULL(t.tot_spend,0) - IFNULL(m.matched_spend,0)) * DIV0(s.asin_sales, ds.day_sales) AS pm_spend FROM india_sales s LEFT JOIN india_pm_direct d ON d.day=s.day AND d.asin=s.asin LEFT JOIN india_pm_total_day t ON t.day=s.day LEFT JOIN india_pm_matched m ON m.day=s.day LEFT JOIN india_day_sales ds ON ds.day=s.day ), tool_cost_monthly AS ( SELECT TRY_TO_DATE(MONTH, \'MM-DD-YYYY\') AS month_start, SUM(TRY_TO_DECIMAL(REPLACE(\"Spend(INR)\",\',\',\'\'),30,5)) AS tool_cost_total_inr FROM vahdam_db.maplemonk.fy27_inputs_tool_cost WHERE UPPER(BUSINESS) = \'AMAZON\' AND TRY_TO_DATE(MONTH, \'MM-DD-YYYY\') IS NOT NULL GROUP BY TRY_TO_DATE(MONTH, \'MM-DD-YYYY\') ), universe AS ( SELECT day,channel,geo,asin FROM actuals UNION SELECT day,channel,geo,asin FROM budget_daily ), asin_resolved AS ( SELECT u.day, u.channel, u.geo, u.asin, m.brand, m.common_sku_id, m.common_sku_description, m.category, m.sub_category, m.amz_category, LEFT(m.common_sku_id, 6) AS pkg6 FROM universe u LEFT JOIN asin_geo_map_dedup m ON m.asin = u.asin AND m.channel = u.channel AND m.geo = u.geo ), pass1 AS ( SELECT u.day, u.channel, u.geo, u.asin, ar.brand, ar.common_sku_id, ar.common_sku_description, ar.category, ar.sub_category, ar.amz_category, ar.pkg6, DATE_TRUNC(\'MONTH\', u.day) AS month_start, COALESCE( fxm.fx, fxg.fx_geo_avg, CASE WHEN gc.currency_local=\'INR\' OR u.geo=\'IN\' THEN 1 END ) AS fx_inr, a.currency_local, a.qty_actual, a.sales_actual_local, CASE WHEN u.geo=\'IN\' THEN ipm.pm_spend ELSE a.pm_spend_actual_local END AS pm_spend_actual_local, CASE WHEN u.geo=\'IN\' THEN 0 ELSE a.google_spend_actual_local END AS google_spend_actual_local, CASE WHEN u.geo = \'UK\' AND ar.category IN (\'Coffee\',\'Supplements\') THEN 0.20 WHEN u.geo = \'UAE\' AND u.channel = \'Amazon_3P\' THEN 0.05 ELSE 0 END AS vat_rate, cbc.cogs_per_unit_inr_csku, cs.cogs_per_unit_inr AS cogs_sheet_inr, CASE WHEN u.geo=\'IN\' THEN cs.cogs_per_unit_inr ELSE COALESCE(cbc.cogs_per_unit_inr_csku, cs.cogs_per_unit_inr * 1.05) END AS cogs_per_unit_inr_p1, baff.outbound_per_unit_local_ff AS ba_out_pu, bpff.outbound_per_unit_local_pkg_ff AS bp_out_pu, baff.budget_month_used, CASE WHEN u.geo=\'IN\' THEN iob.ob_per_unit ELSE COALESCE(baff.outbound_per_unit_local_ff, bpff.outbound_per_unit_local_pkg_ff, baxc.outbound_per_unit_local_xc, bpxc.outbound_per_unit_local_pkg_xc) END AS outbound_per_unit_local_p1, CASE WHEN u.geo=\'IN\' THEN 0 WHEN u.geo=\'UK\' THEN COALESCE(baff.three_pl_per_unit_local_ff, 0) ELSE COALESCE(baff.three_pl_per_unit_local_ff, bpff.three_pl_per_unit_local_pkg_ff, baxc.three_pl_per_unit_local_xc, bpxc.three_pl_per_unit_local_pkg_xc) END AS three_pl_per_unit_local_p1, CASE WHEN u.geo=\'IN\' THEN ipu.storage_per_unit WHEN u.geo=\'UK\' AND u.channel=\'Amazon_1P\' THEN COALESCE(baff.storage_per_unit_local_ff, 0) ELSE COALESCE(baff.storage_per_unit_local_ff, bpff.storage_per_unit_local_pkg_ff, baxc.storage_per_unit_local_xc, bpxc.storage_per_unit_local_pkg_xc) END AS storage_per_unit_local_p1, CASE WHEN u.geo=\'IN\' THEN ipu.lastmile_per_unit WHEN u.geo=\'UK\' AND u.channel=\'Amazon_1P\' THEN COALESCE(baff.lastmile_per_unit_local_ff, 0) WHEN u.channel=\'Amazon_3P\' AND sl.lastmile_per_unit_local_settlement IS NOT NULL THEN sl.lastmile_per_unit_local_settlement WHEN baff.lastmile_per_unit_local_ff IS NOT NULL THEN baff.lastmile_per_unit_local_ff WHEN bpff.lastmile_per_unit_local_pkg_ff IS NOT NULL THEN bpff.lastmile_per_unit_local_pkg_ff ELSE NULL END AS lastmile_per_unit_local_p1, CASE WHEN u.geo=\'IN\' THEN ipu.commission_pct WHEN u.channel=\'Amazon_3P\' AND u.geo IN (\'USA\',\'CA\',\'UK\',\'DE\',\'ES\',\'FR\',\'IT\',\'UAE\',\'AUS\') AND a.qty_actual IS NOT NULL AND a.qty_actual <> 0 AND a.sales_actual_local IS NOT NULL THEN CASE WHEN u.geo = \'USA\' THEN CASE WHEN (a.sales_actual_local / a.qty_actual) < 15 THEN 0.08 ELSE 0.15 END WHEN u.geo = \'CA\' THEN CASE WHEN (a.sales_actual_local / a.qty_actual) < 20 THEN 0.08 ELSE 0.15 END WHEN u.geo = \'UK\' THEN CASE WHEN (a.sales_actual_local / a.qty_actual) < 10 THEN 0.05 ELSE 0.15 END WHEN u.geo IN (\'DE\',\'ES\',\'FR\',\'IT\') THEN CASE WHEN (a.sales_actual_local / a.qty_actual) < 10 THEN 0.05 ELSE 0.15 END WHEN u.geo = \'UAE\' THEN CASE WHEN (a.sales_actual_local / a.qty_actual) < 50 THEN 0.05 ELSE 0.11 END WHEN u.geo = \'AUS\' THEN CASE WHEN (a.sales_actual_local / a.qty_actual) < 20 THEN 0.08 ELSE 0.10 END END WHEN u.channel=\'Amazon_3P\' AND u.geo IN (\'USA\',\'CA\',\'UK\',\'DE\',\'ES\',\'FR\',\'IT\',\'UAE\',\'AUS\') AND (a.qty_actual IS NULL OR a.qty_actual = 0 OR a.sales_actual_local IS NULL) THEN 0 WHEN u.channel=\'Amazon_3P\' AND sl.commission_pct_settlement IS NOT NULL THEN sl.commission_pct_settlement WHEN baff.commission_pct_budget_asin_ff IS NOT NULL THEN baff.commission_pct_budget_asin_ff ELSE NULL END AS commission_pct_p1, COALESCE(baff.has_additional_duty_flag_ff, 0) AS has_additional_duty_flag, bd.qty_budget, bd.sales_budget_local, bd.cogs_budget_local, bd.additional_duty_budget_local, bd.commission_budget_local, bd.outbound_budget_local, bd.three_pl_budget_local, bd.storage_budget_local, bd.last_mile_budget_local, bd.pm_spend_budget_local FROM universe u LEFT JOIN asin_resolved ar ON ar.day=u.day AND ar.channel=u.channel AND ar.geo=u.geo AND ar.asin=u.asin LEFT JOIN actuals a ON a.day=u.day AND a.channel=u.channel AND a.geo=u.geo AND a.asin=u.asin LEFT JOIN budget_daily bd ON bd.day=u.day AND bd.channel=u.channel AND bd.geo=u.geo AND bd.asin=u.asin LEFT JOIN cogs_sheet cs ON cs.common_sku_id=ar.common_sku_id LEFT JOIN cogs_budget_csku cbc ON cbc.common_sku_id=ar.common_sku_id LEFT JOIN settlement_latest sl ON sl.asin=u.asin AND sl.geo=u.geo LEFT JOIN india_perunit ipu ON u.geo=\'IN\' AND ipu.asin=u.asin LEFT JOIN india_ob iob ON u.geo=\'IN\' AND iob.asin=u.asin LEFT JOIN india_pm ipm ON u.geo=\'IN\' AND ipm.day=u.day AND ipm.asin=u.asin LEFT JOIN fx_map fxm ON fxm.geo=u.geo AND fxm.month_start=DATE_TRUNC(\'MONTH\',u.day) LEFT JOIN fx_geo_avg fxg ON fxg.geo=u.geo LEFT JOIN geo_currency gc ON gc.geo=u.geo LEFT JOIN budget_asin_ff baff ON baff.geo=u.geo AND baff.channel=u.channel AND baff.month_start=DATE_TRUNC(\'MONTH\',u.day) AND baff.asin=u.asin LEFT JOIN budget_pkg_ff bpff ON bpff.geo=u.geo AND bpff.channel=u.channel AND bpff.month_start=DATE_TRUNC(\'MONTH\',u.day) AND bpff.pkg6=ar.pkg6 LEFT JOIN budget_asin_anychannel baxc ON baxc.geo=u.geo AND baxc.month_start=DATE_TRUNC(\'MONTH\',u.day) AND baxc.asin=u.asin LEFT JOIN budget_pkg_anychannel bpxc ON bpxc.geo=u.geo AND bpxc.month_start=DATE_TRUNC(\'MONTH\',u.day) AND bpxc.pkg6=ar.pkg6 ), actuals_pct AS ( SELECT geo, channel, month_start, CASE WHEN SUM(CASE WHEN cogs_per_unit_inr_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local*fx_inr END)>0 THEN SUM(CASE WHEN cogs_per_unit_inr_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*cogs_per_unit_inr_p1 END) / NULLIF(SUM(CASE WHEN cogs_per_unit_inr_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local*fx_inr END),0) END AS cogs_pct_actual, CASE WHEN SUM(CASE WHEN outbound_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN outbound_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*outbound_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN outbound_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS outbound_pct_actual, CASE WHEN SUM(CASE WHEN three_pl_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN three_pl_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*three_pl_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN three_pl_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS three_pl_pct_actual, CASE WHEN SUM(CASE WHEN storage_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN storage_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*storage_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN storage_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS storage_pct_actual, CASE WHEN SUM(CASE WHEN lastmile_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN lastmile_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*lastmile_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN lastmile_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS lastmile_pct_actual, CASE WHEN SUM(CASE WHEN commission_pct_p1 IS NOT NULL AND sales_actual_local IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN commission_pct_p1 IS NOT NULL AND sales_actual_local IS NOT NULL THEN sales_actual_local*commission_pct_p1 END) / NULLIF(SUM(CASE WHEN commission_pct_p1 IS NOT NULL AND sales_actual_local IS NOT NULL THEN sales_actual_local END),0) END AS commission_pct_actual FROM pass1 GROUP BY geo, channel, month_start ), actuals_pct_geo AS ( SELECT geo, month_start, CASE WHEN SUM(CASE WHEN outbound_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN outbound_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*outbound_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN outbound_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS outbound_pct_actual_g, CASE WHEN SUM(CASE WHEN three_pl_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN three_pl_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*three_pl_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN three_pl_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS three_pl_pct_actual_g, CASE WHEN SUM(CASE WHEN storage_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END)>0 THEN SUM(CASE WHEN storage_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN qty_actual*storage_per_unit_local_p1 END) / NULLIF(SUM(CASE WHEN storage_per_unit_local_p1 IS NOT NULL AND qty_actual IS NOT NULL THEN sales_actual_local END),0) END AS storage_pct_actual_g FROM pass1 GROUP BY geo, month_start ), monthly_sales_inr AS ( SELECT month_start, SUM(sales_actual_local * fx_inr) AS total_sales_inr_month FROM pass1 WHERE sales_actual_local IS NOT NULL AND fx_inr IS NOT NULL GROUP BY month_start ), final AS ( SELECT p.day, p.channel, p.geo, p.asin, p.brand, p.common_sku_id, p.common_sku_description, p.category, p.sub_category, p.amz_category, p.month_start, p.fx_inr, p.currency_local, p.qty_actual, p.sales_actual_local AS sales_actual_local_gross, p.sales_actual_local / (1 + p.vat_rate) AS sales_actual_local_net, p.vat_rate, p.pm_spend_actual_local, p.google_spend_actual_local, COALESCE(p.cogs_per_unit_inr_p1, p.sales_actual_local*p.fx_inr*ap.cogs_pct_actual/NULLIF(p.qty_actual,0)) AS cogs_per_unit_inr_used, COALESCE(p.outbound_per_unit_local_p1, p.sales_actual_local*ap.outbound_pct_actual/NULLIF(p.qty_actual,0), p.sales_actual_local*apg.outbound_pct_actual_g/NULLIF(p.qty_actual,0)) AS outbound_per_unit_local_used, COALESCE(p.three_pl_per_unit_local_p1, p.sales_actual_local*ap.three_pl_pct_actual/NULLIF(p.qty_actual,0), p.sales_actual_local*apg.three_pl_pct_actual_g/NULLIF(p.qty_actual,0)) AS three_pl_per_unit_local_used, COALESCE(p.storage_per_unit_local_p1, p.sales_actual_local*ap.storage_pct_actual/NULLIF(p.qty_actual,0), p.sales_actual_local*apg.storage_pct_actual_g/NULLIF(p.qty_actual,0)) AS storage_per_unit_local_used, COALESCE(p.lastmile_per_unit_local_p1, p.sales_actual_local*ap.lastmile_pct_actual/NULLIF(p.qty_actual,0)) AS lastmile_per_unit_local_used, COALESCE(p.commission_pct_p1, ap.commission_pct_actual) AS commission_pct_used, p.has_additional_duty_flag, CASE WHEN p.geo=\'IN\' THEN (CASE WHEN p.cogs_sheet_inr IS NOT NULL THEN \'N\' ELSE \'Y\' END) WHEN p.cogs_per_unit_inr_csku IS NOT NULL THEN \'N\' ELSE \'Y\' END AS cogs_fallback, CASE WHEN p.geo=\'IN\' THEN (CASE WHEN p.outbound_per_unit_local_p1 IS NOT NULL THEN \'N\' ELSE \'Y\' END) WHEN p.ba_out_pu IS NOT NULL THEN \'N\' ELSE \'Y\' END AS outbound_fallback, CASE WHEN p.budget_month_used IS NULL THEN \'NO_BUDGET\' WHEN p.budget_month_used <> p.month_start THEN \'Y\' ELSE \'N\' END AS budget_carried_forward, CASE WHEN p.sales_actual_local IS NOT NULL AND p.fx_inr IS NOT NULL AND ms.total_sales_inr_month > 0 AND tcm.tool_cost_total_inr IS NOT NULL THEN tcm.tool_cost_total_inr * (p.sales_actual_local * p.fx_inr) / ms.total_sales_inr_month ELSE 0 END AS tool_cost_actual_inr_used, p.qty_budget, p.sales_budget_local, p.cogs_budget_local, p.additional_duty_budget_local, p.commission_budget_local, p.outbound_budget_local, p.three_pl_budget_local, p.storage_budget_local, p.last_mile_budget_local, p.pm_spend_budget_local FROM pass1 p LEFT JOIN actuals_pct ap ON ap.geo=p.geo AND ap.channel=p.channel AND ap.month_start=p.month_start LEFT JOIN actuals_pct_geo apg ON apg.geo=p.geo AND apg.month_start=p.month_start LEFT JOIN tool_cost_monthly tcm ON tcm.month_start=p.month_start LEFT JOIN monthly_sales_inr ms ON ms.month_start=p.month_start ) SELECT day, channel, geo, asin, brand, common_sku_id, common_sku_description, category, sub_category, amz_category AS AMZ_Category, currency_local, fx_inr, qty_actual, sales_actual_local_net AS sales_actual_local, qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0) AS cogs_actual_local, CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(sales_actual_local_gross,0) * 0.10 * 0.25 ELSE 0 END AS additional_duty_actual_local, qty_actual * outbound_per_unit_local_used AS outbound_actual_local, qty_actual * three_pl_per_unit_local_used AS three_pl_actual_local, qty_actual * storage_per_unit_local_used AS storage_actual_local, qty_actual * lastmile_per_unit_local_used AS last_mile_actual_local, sales_actual_local_gross * commission_pct_used AS commission_actual_local, sales_actual_local_net - COALESCE(qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(sales_actual_local_gross,0) * 0.10 * 0.25 ELSE 0 END,0) - COALESCE(qty_actual * outbound_per_unit_local_used,0) - COALESCE(qty_actual * three_pl_per_unit_local_used,0) - COALESCE(qty_actual * storage_per_unit_local_used,0) - COALESCE(qty_actual * lastmile_per_unit_local_used,0) - COALESCE(sales_actual_local_gross * commission_pct_used,0) AS cm1_actual_local, pm_spend_actual_local, google_spend_actual_local, tool_cost_actual_inr_used / NULLIF(fx_inr,0) AS tool_cost_actual_local, ( sales_actual_local_net - COALESCE(qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(sales_actual_local_gross,0) * 0.10 * 0.25 ELSE 0 END,0) - COALESCE(qty_actual * outbound_per_unit_local_used,0) - COALESCE(qty_actual * three_pl_per_unit_local_used,0) - COALESCE(qty_actual * storage_per_unit_local_used,0) - COALESCE(qty_actual * lastmile_per_unit_local_used,0) - COALESCE(sales_actual_local_gross * commission_pct_used,0) ) - COALESCE(pm_spend_actual_local,0) - COALESCE(google_spend_actual_local,0) - COALESCE(tool_cost_actual_inr_used / NULLIF(fx_inr,0),0) AS cm2_actual_local, sales_actual_local_net * fx_inr AS sales_actual_inr, qty_actual * cogs_per_unit_inr_used AS cogs_actual_inr, CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(sales_actual_local_gross,0) * 0.10 * 0.25 * fx_inr ELSE 0 END AS additional_duty_actual_inr, qty_actual * outbound_per_unit_local_used * fx_inr AS outbound_actual_inr, qty_actual * three_pl_per_unit_local_used * fx_inr AS three_pl_actual_inr, qty_actual * storage_per_unit_local_used * fx_inr AS storage_actual_inr, qty_actual * lastmile_per_unit_local_used * fx_inr AS last_mile_actual_inr, sales_actual_local_gross * commission_pct_used * fx_inr AS commission_actual_inr, ( sales_actual_local_net - COALESCE(qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(sales_actual_local_gross,0) * 0.10 * 0.25 ELSE 0 END,0) - COALESCE(qty_actual * outbound_per_unit_local_used,0) - COALESCE(qty_actual * three_pl_per_unit_local_used,0) - COALESCE(qty_actual * storage_per_unit_local_used,0) - COALESCE(qty_actual * lastmile_per_unit_local_used,0) - COALESCE(sales_actual_local_gross * commission_pct_used,0) ) * fx_inr AS cm1_actual_inr, pm_spend_actual_local * fx_inr AS pm_spend_actual_inr, google_spend_actual_local * fx_inr AS google_spend_actual_inr, tool_cost_actual_inr_used AS tool_cost_actual_inr, (( sales_actual_local_net - COALESCE(qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(sales_actual_local_gross,0) * 0.10 * 0.25 ELSE 0 END,0) - COALESCE(qty_actual * outbound_per_unit_local_used,0) - COALESCE(qty_actual * three_pl_per_unit_local_used,0) - COALESCE(qty_actual * storage_per_unit_local_used,0) - COALESCE(qty_actual * lastmile_per_unit_local_used,0) - COALESCE(sales_actual_local_gross * commission_pct_used,0) ) - COALESCE(pm_spend_actual_local,0) - COALESCE(google_spend_actual_local,0) ) * fx_inr - COALESCE(tool_cost_actual_inr_used,0) AS cm2_actual_inr, qty_budget, sales_budget_local, cogs_budget_local, additional_duty_budget_local, commission_budget_local, outbound_budget_local, three_pl_budget_local, storage_budget_local, last_mile_budget_local, ( COALESCE(sales_budget_local,0) - COALESCE(cogs_budget_local,0) - COALESCE(additional_duty_budget_local,0) - COALESCE(commission_budget_local,0) - COALESCE(outbound_budget_local,0) - COALESCE(three_pl_budget_local,0) - COALESCE(storage_budget_local,0) - COALESCE(last_mile_budget_local,0) ) AS cm1_budget_local, pm_spend_budget_local, ( COALESCE(sales_budget_local,0) - COALESCE(cogs_budget_local,0) - COALESCE(additional_duty_budget_local,0) - COALESCE(commission_budget_local,0) - COALESCE(outbound_budget_local,0) - COALESCE(three_pl_budget_local,0) - COALESCE(storage_budget_local,0) - COALESCE(last_mile_budget_local,0) - COALESCE(pm_spend_budget_local,0) ) AS cm2_budget_local, sales_budget_local * fx_inr AS sales_budget_inr, cogs_budget_local * fx_inr AS cogs_budget_inr, additional_duty_budget_local * fx_inr AS additional_duty_budget_inr, commission_budget_local * fx_inr AS commission_budget_inr, outbound_budget_local * fx_inr AS outbound_budget_inr, three_pl_budget_local * fx_inr AS three_pl_budget_inr, last_mile_budget_local * fx_inr AS last_mile_budget_inr, ( COALESCE(sales_budget_local,0) - COALESCE(cogs_budget_local,0) - COALESCE(additional_duty_budget_local,0) - COALESCE(commission_budget_local,0) - COALESCE(outbound_budget_local,0) - COALESCE(three_pl_budget_local,0) - COALESCE(storage_budget_local,0) - COALESCE(last_mile_budget_local,0) ) * fx_inr AS cm1_budget_inr, pm_spend_budget_local * fx_inr AS pm_spend_budget_inr, ( COALESCE(sales_budget_local,0) - COALESCE(cogs_budget_local,0) - COALESCE(additional_duty_budget_local,0) - COALESCE(commission_budget_local,0) - COALESCE(outbound_budget_local,0) - COALESCE(three_pl_budget_local,0) - COALESCE(storage_budget_local,0) - COALESCE(last_mile_budget_local,0) - COALESCE(pm_spend_budget_local,0) ) * fx_inr AS cm2_budget_inr, cogs_fallback, outbound_fallback, CASE WHEN commission_pct_used IS NULL THEN \'Y\' ELSE \'N\' END AS commission_fallback, CASE WHEN lastmile_per_unit_local_used IS NULL THEN \'Y\' ELSE \'N\' END AS lastmile_fallback, CASE WHEN three_pl_per_unit_local_used IS NULL THEN \'Y\' ELSE \'N\' END AS three_pl_fallback, CASE WHEN storage_per_unit_local_used IS NULL THEN \'Y\' ELSE \'N\' END AS storage_fallback, budget_carried_forward, CASE WHEN qty_actual IS NULL THEN \'NO_ACTUALS\' WHEN cogs_per_unit_inr_used IS NOT NULL AND commission_pct_used IS NOT NULL AND outbound_per_unit_local_used IS NOT NULL AND lastmile_per_unit_local_used IS NOT NULL AND storage_per_unit_local_used IS NOT NULL AND three_pl_per_unit_local_used IS NOT NULL THEN \'COMPLETE\' ELSE \'PARTIAL\' END AS cost_completeness FROM final );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

